from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

from Team_Phoenix_Library import phoenix_gyro_spin_turn_the_old_way

# Set up.
leefftt_DDRRIIVVEE_____ = Motor(Port.E, Direction.COUNTERCLOCKWISE)
wat54sacvyujyuc_yu_crftrx = Motor(Port.D, Direction.CLOCKWISE)
drive_base_ria = DriveBase(leefftt_DDRRIIVVEE_____, wat54sacvyujyuc_yu_crftrx, 56, 114)

def runoldbluemission_2(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    drive_base.turn(100)
    drive_base.straight(590)
    drive_base.settings(turn_rate=60)
    drive_base.turn(-75)
    drive_base.straight(30)
    drive_base.straight(0)
    drive_base.settings(turn_rate=150)
    drive_base.turn(-60)
    drive_base.turn(40)
    drive_base.straight(10)
    drive_base.turn(-40)
    drive_base.turn(30)
    drive_base.straight(-30)
    drive_base.turn(60)
    drive_base.straight(-300)
    drive_base.turn(-20)
    drive_base.straight(-350)

def runoldbluemission(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    phoenix_gyro_spin_turn_the_old_way(125, 100, 45, 100, 'right', drive_base, left_drive, right_drive)
    drive_base.straight(560)
    phoenix_gyro_spin_turn_the_old_way(60, -75, 60, -75, 'left', drive_base, left_drive, right_drive)
    drive_base.straight(30)
    phoenix_gyro_spin_turn_the_old_way(100, -60, 100, -60, 'left', drive_base, left_drive, right_drive)
    phoenix_gyro_spin_turn_the_old_way(100, 40, 100, 40, 'right', drive_base, left_drive, right_drive)
    drive_base.straight(10)
    phoenix_gyro_spin_turn_the_old_way(100, -40, 100, -40, 'left', drive_base, left_drive, right_drive)
    phoenix_gyro_spin_turn_the_old_way(100, 30, 100, 30, 'right', drive_base, left_drive, right_drive)
    drive_base.straight(-30)
    phoenix_gyro_spin_turn_the_old_way(100, 60, 100, 60, 'right', drive_base, left_drive, right_drive)
    drive_base.straight(-300)
    phoenix_gyro_spin_turn_the_old_way(100, -20, 100, -20, 'left', drive_base, left_drive, right_drive)
    drive_base.straight(-350)


# The main program starts here.
runoldbluemission(drive_base_ria, leefftt_DDRRIIVVEE_____, wat54sacvyujyuc_yu_crftrx, 0, 0)
